<?php
declare(strict_types=1);namespace Vendi\Sales;use PDO;use RuntimeException;use Vendi\Support\Money;use Vendi\Payments\PaymentProcessor;use Vendi\Branches\BranchClock;
final class SaleService{public function __construct(private PDO $db,private ?InventoryConsumptionService $inventory=null,private ?PaymentProcessor $paymentProcessor=null){}
 public function checkout(int$b,int$branch,int$u,?int$customer,array$items,array$payments,string$key):int{if(!$items)throw new RuntimeException('La venta está vacía.');if(!$key)throw new RuntimeException('Falta llave de idempotencia.');$this->db->beginTransaction();try{$dup=$this->db->prepare("SELECT id FROM sales WHERE business_id=? AND idempotency_key=? LIMIT 1");$dup->execute([$b,$key]);if($id=$dup->fetchColumn()){$this->db->commit();return(int)$id;}$sub=$disc=$tax=$total=$cost=0.0;$norm=[];foreach($items as$i){$p=$this->db->prepare("SELECT id,name,price,cost,tax_rate FROM products WHERE id=? AND business_id=? AND active=1 FOR UPDATE");$p->execute([(int)$i['product_id'],$b]);$product=$p->fetch();if(!$product)throw new RuntimeException('Producto inválido.');$qty=(float)($i['qty']??$i['quantity']??0);if($qty<=0)throw new RuntimeException('Cantidad inválida.');$price=isset($i['price'])?(float)$i['price']:(float)$product['price'];$line=Money::calculateLine($qty,$price,(float)($i['discount_percent']??0),(float)$product['tax_rate']);$norm[]=[$product,$qty,$price,$line,$i];$sub+=$line['gross'];$disc+=$line['discount'];$tax+=$line['tax'];$total+=$line['total'];$cost+=(float)$product['cost']*$qty;}$processed=($this->paymentProcessor??new PaymentProcessor($this->db))->validate($b,$branch,$payments,Money::round($total));$payments=$processed['payments'];$change=$processed['change'];$cash=$this->db->prepare("SELECT id FROM cash_sessions WHERE business_id=? AND branch_id=? AND user_id=? AND status='open' ORDER BY id DESC LIMIT 1 FOR UPDATE");$cash->execute([$b,$branch,$u]);$cashId=$cash->fetchColumn();if(!$cashId)throw new RuntimeException('Debes abrir caja antes de cobrar.');if(Money::round(array_sum(array_column($payments,'amount')))<Money::round($total))throw new RuntimeException('Pago insuficiente.');$utc=(new BranchClock($this->db))->utcSql($b,$branch);$s=$this->db->prepare("INSERT INTO sales(business_id,branch_id,user_id,customer_id,status,subtotal,discount,tax,total,cost_total,change_total,idempotency_key,completed_at,completed_at_utc) VALUES(?,?,?,?,'completed',?,?,?,?,?,?,?,?,?)");$s->execute([$b,$branch,$u,$customer,Money::round($sub),Money::round($disc),Money::round($tax),Money::round($total),Money::round($cost),$change,$key,$utc,$utc]);$sale=(int)$this->db->lastInsertId();foreach($norm as[$p,$qty,$price,$line,$raw]){$desc=$p['name'].(!empty($raw['variant_name'])?' · '.$raw['variant_name']:'');$si=$this->db->prepare("INSERT INTO sale_items(sale_id,product_id,variant_id,selected_options_json,description,qty,unit_price,unit_cost,discount,tax,line_total) VALUES(?,?,?,?,?,?,?,?,?,?,?)");$si->execute([$sale,$p['id'],$raw['variant_id']??null,json_encode($raw['selected_options']??[],JSON_UNESCAPED_UNICODE),$desc,$qty,$price,$p['cost'],$line['discount'],$line['tax'],$line['total']]);$item=(int)$this->db->lastInsertId();if($this->inventory)$this->inventory->consume($b,$branch,$u,$sale,$item,$raw+['qty'=>$qty]);else{$this->db->prepare("UPDATE inventory SET qty=qty-? WHERE business_id=? AND branch_id=? AND product_id=? AND qty>=?")->execute([$qty,$b,$branch,$p['id'],$qty]);}}foreach($payments as$pay){if((float)$pay['amount']<=0)continue;$this->db->prepare("INSERT INTO payments(sale_id,cash_session_id,payment_method_id,method,amount,reference,change_amount) VALUES(?,?,?,?,?,?,?)")->execute([$sale,$cashId,$pay['payment_method_id'],$pay['method'],Money::round((float)$pay['amount']),$pay['reference']??null,$pay['allows_change']?$change:0]);if($pay['affects_cash_drawer'])$this->db->prepare("INSERT INTO cash_movements(business_id,branch_id,cash_session_id,user_id,type,amount,reference_type,reference_id) VALUES(?,?,?,?,'sale',?,'sale',?)")->execute([$b,$branch,$cashId,$u,Money::round((float)$pay['amount']-($pay['allows_change']?$change:0)),$sale]);}$this->db->commit();return$sale;}catch(\Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
}